private static int parsePositionAnchor(String s) {
    try {
        switch (s) {
            case "start":    return Cue.ANCHOR_TYPE_START;
            case "middle":  return Cue.ANCHOR_TYPE_MIDDLE;
            case "end":     return Cue.ANCHOR_TYPE_END;
            default:
                Log.w(TAG, "Invalid anchor value: " + s);
                return Cue.TYPE_UNSET;
        }
    } catch (NullPointerException e) {
        Log.w(TAG, "Null anchor value");
        return Cue.TYPE_UNSET;
    }
}
